/bin/bash -lc "python3 - <<'PY'
import sim, mujoco
s=sim.Sim()
m=s.model
def list_objs(kind,name):
    typ={'body':mujoco.mjtObj.mjOBJ_BODY,'geom':mujoco.mjtObj.mjOBJ_GEOM,'site':mujoco.mjtObj.mjOBJ_SITE,'camera':mujoco.mjtObj.mjOBJ_CAMERA}
    n={'body':m.nbody,'geom':m.ngeom,'site':m.nsite,'camera':m.ncamera}[kind]
    arr=[]
    for i in range(n):
        nm=mujoco.mj_id2name(m,typ[kind],i)
        if nm is not None:
            arr.append(nm)
    return arr
print('bodies',len(list_objs('body',None)))
for b in list_objs('body',None):
    pass
print('bodies:');
for i in range(s.model.nbody):
    nm=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if nm is not None:
        print(i,nm)
print('geoms:')
for i in range(s.model.ngeom):
    nm=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_GEOM,i)
    if nm is not None:
        print(i,nm)
print('sites:')
for i in range(s.model.nsite):
    nm=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_SITE,i)
    if nm is not None:
        print(i,nm)
PY"

